def get_ft(path):
    with open(path,'rb') as f:
        assert f.read(4)==b'GGUF'
        _ver, _nt, nkv = struct.unpack('<IQQ', f.read(20))
        def rstr():
            n = struct.unpack('<Q', f.read(8))[0]
            return f.read(n).decode('utf-8','replace')
        def rval(t):
            if t==8: return rstr()
            if t in (0,1,2,3): return struct.unpack('<i', f.read(4))[0]
            if t in (6,7): return struct.unpack('<q', f.read(8))[0]
            if t==4: return struct.unpack('<f', f.read(4))[0]
            if t==5: return struct.unpack('<d', f.read(8))[0]
            if t==9:
                t2 = struct.unpack('<I', f.read(4))[0]
                n = struct.unpack('<Q', f.read(8))[0]
                for _ in range(n): rval(t2)
                return None
            if t in (10,11,12):
                t2 = struct.unpack('<I', f.read(4))[0]
                n = struct.unpack('<Q', f.read(8))[0]
                for _ in range(n): rval(t2)
                return None
            return None
        for _ in range(nkv):
            k = rstr()
            t = struct.unpack('<I', f.read(4))[0]
            v = rval(t)
            if k == 'general.file_type':
                return v, FT.get(v, '?')
        return None, None
