import struct
from gguf.constants import GGUFValueType as T

SIZES = {T.UINT8:1, T.INT8:1, T.BOOL:1, T.UINT16:2, T.INT16:2,
         T.UINT32:4, T.INT32:4, T.FLOAT32:4, T.UINT64:8, T.INT64:8, T.FLOAT64:8}
FMT = {T.INT8:'b', T.BOOL:'?', T.UINT16:'H', T.INT16:'h', T.UINT32:'I',
       T.INT32:'i', T.FLOAT32:'f', T.UINT64:'Q', T.INT64:'q', T.FLOAT64:'d'}

def read_str(data, off):
    ln = struct.unpack('<Q', data[off:off+8])[0]; off += 8
    return data[off:off+ln].decode(), off + ln

def parse(path):
    data = open(path, 'rb').read()
    off = 8
    n_tensors = struct.unpack('<Q', data[off:off+8])[0]; off += 8
    n_kv = struct.unpack('<Q', data[off:off+8])[0]; off += 8
    hits = []
    for _ in range(n_kv):
        key, off = read_str(data, off)
        vt = T(struct.unpack('<I', data[off:off+4])[0]); off += 4
        if vt == T.ARRAY:
            et = T(struct.unpack('<I', data[off:off+4])[0]); off += 4
            cnt = struct.unpack('<Q', data[off:off+8])[0]; off += 8
            arr = []
            for _ in range(cnt):
                if et == T.STRING:
                    s, off = read_str(data, off); arr.append(s)
                elif et in FMT:
                    sz = SIZES[et]
                    arr.append(struct.unpack('<'+FMT[et], data[off:off+sz])[0]); off += sz
                else:
                    off += 8; arr.append('?')
            val = arr
        elif vt == T.STRING:
            val, off = read_str(data, off)
        elif vt in FMT:
            sz = SIZES[vt]
            val = struct.unpack('<'+FMT[vt], data[off:off+sz])[0]; off += sz
        else:
            off += 8; val = '?'
        if 'rope' in key.lower() or 'mrope' in key.lower() or 'section' in key.lower() or 'context_length' in key.lower() or 'arch' in key.lower():
            hits.append((key, val))
    return n_tensors, n_kv, hits

