import struct
from gguf.constants import GGUFValueType as T

SIZES = {T.UINT8:1, T.INT8:1, T.BOOL:1, T.UINT16:2, T.INT16:2,
         T.UINT32:4, T.INT32:4, T.FLOAT32:4, T.UINT64:8, T.INT64:8, T.FLOAT64:8}
FMT = {T.INT8:'b', T.BOOL:'?', T.UINT16:'H', T.INT16:'h', T.UINT32:'I',
       T.INT32:'i', T.FLOAT32:'f', T.UINT64:'Q', T.INT64:'q', T.FLOAT64:'d'}

data = open('/tmp/opencode/qwen_hf_partial.gguf','rb').read()
N = len(data)
print("arquivo:", N, "bytes")

def rd(fmt, off, size):
    if off + size > N:
        raise EOFError(f"fora dos limites: off={off} size={size} N={N}")
    return struct.unpack_from('<'+fmt, data, off)[0], off + size

off = 8
n_tensors, off = rd('Q', off, 8)
n_kv, off = rd('Q', off, 8)
print(f"tensors={n_tensors} kv={n_kv}")

def read_str(off):
    ln, off = rd('Q', off, 8)
    if off + ln > N: raise EOFError(f"string len={ln} estoura: off={off} N={N}")
    return data[off:off+ln].decode(errors='replace'), off + ln

for i in range(n_kv):
    try:
        key, off = read_str(off)
        vt_raw, off = rd('I', off, 4)
        vt = T(vt_raw)
        if vt == T.ARRAY:
            et_raw, off = rd('I', off, 4)
            cnt, off = rd('Q', off, 8)
            et = T(et_raw)
            arr = []
            for _ in range(cnt):
                if et == T.STRING:
                    s, off = read_str(off); arr.append(s)
                elif et in FMT:
                    sz = SIZES[et]; v, off = rd(FMT[et], off, sz); arr.append(v)
                else:
                    v, off = rd('Q', off, 8); arr.append('?')
            val = arr
        elif vt == T.STRING:
            val, off = read_str(off)
        elif vt in FMT:
            sz = SIZES[vt]; val, off = rd(FMT[vt], off, sz)
        else:
            val, off = rd('Q', off, 8)
        tag = '' if not ('rope' in key.lower() or 'mrope' in key.lower() or 'llm' in key.lower() or 'arch' in key.lower()) else '  <<<'
        if tag: print(f"  [{i}] {key} = {val}{tag}")
    except EOFError as e:
        print(f"  [{i}] key={key!r} QUEBROU: {e}")
        break
